import java.util.Scanner;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[] sorted = {n, m};
        if (sorted[0] > sorted[1]) {
            int temp = sorted[0];
            sorted[0] = sorted[1];
            sorted[1] = temp;
        }
        n = sorted[0];
        m = sorted[1];

        int c;
        if (n == 1) {
            c = Math.min(m % 6, 6 - m % 6);
        } else if (n == 2) {
            Map<Integer, Integer> map = Map.of(2, 4, 3, 2, 7, 2);
            c = map.getOrDefault(m, 0);
        } else {
            c = (n & 1) * (m & 1);
        }
        System.out.println(n * m - c);
    }
}
